/// <reference path="../pb_data/types.d.ts" />

// StackBlaze boot hook. Runs once per start, after PocketBase has opened its
// database and before it serves. Each step is inert when its variable is unset.
//
// 1. First superuser: PB_ADMIN_EMAIL / PB_ADMIN_PASSWORD (generated by the
//    template). Created only while no real superuser exists, so the public
//    install link (/_/#/pbinstall/<token>) is never needed and a password the
//    owner changes later is never reset.
// 2. Public URL: PB_APP_URL fills Settings > Application URL (used in mail
//    links) while it is still upstream's default.
// 3. Mail: the platform's Email add-on injects SMTP_HOST, SMTP_PORT,
//    SMTP_USER, SMTP_PASSWORD and SMTP_FROM ("Name <addr>" or "addr"). Without
//    them PocketBase falls back to a sendmail binary the image does not have,
//    so verification, reset and OTP mails would fail. While the add-on is live
//    its relay settings are applied on every start.
onBootstrap((e) => {
  e.next()

  const app = e.app
  const env = (k) => ($os.getenv(k) || '').trim()

  // 1. First superuser
  const email = env('PB_ADMIN_EMAIL')
  const password = env('PB_ADMIN_PASSWORD')
  if (email && password) {
    const real = app.countRecords(
      '_superusers',
      $dbx.not($dbx.hashExp({ email: '__pbinstaller@example.com' })),
    )
    if (real === 0) {
      const su = new Record(app.findCollectionByNameOrId('_superusers'))
      su.setEmail(email)
      su.setPassword(password)
      app.save(su)
      app.logger().info('StackBlaze: created the first superuser', 'email', email)
    }
  }

  const settings = app.settings()
  let changed = []

  // 2. Public URL
  const url = env('PB_APP_URL').replace(/\/+$/, '')
  if (url && /^https?:\/\//.test(url)) {
    const cur = settings.meta.appURL
    if (!cur || cur === 'http://localhost:8090') {
      settings.meta.appURL = url
      changed.push('appURL')
    }
  }

  // 3. Mail from the Email add-on
  const host = env('SMTP_HOST')
  if (host) {
    const from = env('SMTP_FROM')
    const m = from.match(/^\s*"?([^"<]*?)"?\s*<([^>]+)>\s*$/)
    const address = m ? m[2].trim() : from
    const name = m ? m[1].trim() : ''
    const want = {
      enabled: true,
      host: host,
      port: parseInt(env('SMTP_PORT') || '587', 10),
      username: env('SMTP_USER'),
      password: env('SMTP_PASSWORD'),
      tls: false, // the relay is STARTTLS on 587; PocketBase upgrades when tls=false
    }
    const smtp = settings.smtp
    for (const k of Object.keys(want)) {
      if (smtp[k] !== want[k]) {
        smtp[k] = want[k]
        changed.push('smtp.' + k)
      }
    }
    if (address && settings.meta.senderAddress !== address) {
      settings.meta.senderAddress = address
      changed.push('senderAddress')
    }
    // Keep a sender name the owner chose; replace only upstream's default.
    if (name && (!settings.meta.senderName || settings.meta.senderName === 'Support')) {
      if (settings.meta.senderName !== name) {
        settings.meta.senderName = name
        changed.push('senderName')
      }
    }
  }

  if (changed.length) {
    app.save(settings)
    // Names only: never log values (the SMTP password is among them).
    app.logger().info('StackBlaze: applied settings', 'fields', changed.join(','))
  }
})
